import json, requests, traceback

def head(url):
    try:
        r = requests.head(url, headers={"User-Agent":"Mozilla/5.0"}, timeout=60, allow_redirects=True)
        return r.status_code, r.headers.get("Content-Length"), r.url
    except Exception as e:
        return "ERR", str(e), url

def get(url, params=None, headers=None, timeout=90):
    h={"User-Agent":"Mozilla/5.0"}
    if headers: h.update(headers)
    return requests.get(url, params=params, headers=h, timeout=timeout)

print("### 1) Ensembl VEP by region with AlphaMissense flag")
for params in [
    {"AlphaMissense": 1},
    {"alphamissense": 1},
]:
    try:
        r = get("https://rest.ensembl.org/vep/human/region/17:7577121-7577121/ENST00000369397",
                params=params, headers={"Content-Type":"application/json"})
        print("params:", params, "status:", r.status_code)
        if r.status_code == 200:
            d = r.json()
            # find keys mentioning alpha
            print("top-level keys:", list(d[0].keys()) if d else None)
            def walk(o, path=""):
                if isinstance(o, dict):
                    for k,v in o.items():
                        if "alpha" in k.lower() or "am_" in k.lower():
                            print("  HIT", path+"/"+k, "=", v if not isinstance(v,(dict,list)) else str(v)[:300])
                        walk(v, path+"/"+k)
                elif isinstance(o, list):
                    for i,v in enumerate(o[:3]):
                        walk(v, path+f"[{i}]")
            walk(d)
            open("/tmp/vep_r175h.json","w").write(json.dumps(d, indent=2))
        else:
            print(r.text[:500])
    except Exception as e:
        traceback.print_exc()

print()
print("### 2) Ensembl VEP by rsID (Ensembl variation API)")
for ident in ["rs760043118"]:
    for endpoint in ["https://rest.ensembl.org/vep/human/id/%s" % ident,
                     "https://rest.ensembl.org/variation/human/%s" % ident]:
        try:
            r = get(endpoint, params={"AlphaMissense":1, "content-type":"application/json"}, headers={"Content-Type":"application/json"})
            print(endpoint, "->", r.status_code, len(r.text))
            if r.status_code==200:
                t=r.text
                print(t[:300].replace("\n"," "))
                open("/tmp/%s.json"%ident.replace("/","_"),"w").write(t)
        except Exception as e:
            print(endpoint,"ERR",e)

print()
print("### 3) Google Cloud Storage: AlphaMissense public release files")
for u in [
  "https://storage.googleapis.com/gcp-public-data--alphamissense/AlphaMissense_aa_substitutions.tsv.gz",
  "https://storage.googleapis.com/gcp-public-data--alphamissense/AlphaMissense_by_transcript.tsv.gz",
  "https://storage.googleapis.com/gcp-public-data--alphamissense/AlphaMissense_variant_summary.tsv.gz",
]:
    print(u.split("/")[-1], "->", head(u))
try:
    r = get("https://storage.googleapis.com/storage/v1/b/gcp-public-data--alphamissense/o", params={"prefix":"", "maxResults":100})
    print("bucket listing status:", r.status_code)
    if r.status_code==200:
        for it in r.json().get("items", []):
            print("  ", it["name"], it.get("size"))
except Exception as e:
    print("listing err", e)
