import json, requests, traceback, re

H={"User-Agent":"Mozilla/5.0","Content-Type":"application/json"}

def get(url, params=None, timeout=90):
    return requests.get(url, params=params, headers=H, timeout=timeout)

print("### 1) Ensembl VEP REST supported parameters (looking for AlphaMissense)")
try:
    r=get("https://rest.ensembl.org/documentation/info/vep", params={"content-type":"application/json"})
    txt=r.text
    hits=[p for p in re.findall(r'"name"\s*:\s*"([^"]+)"', txt) if "lpha" in p or "plice" in p or p.lower() in ("lo f","lof","cadd","dbnsfp","plugins")]
    print("candidate params:", sorted(set(hits)))
    print("status", r.status_code)
except Exception as e:
    traceback.print_exc()

print()
print("### 2) ClinVar / dbSNP lookup for TP53 R175H")
try:
    r=get("https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi",
          params={"db":"clinvar","term":"TP53[gene] AND R175H","retmode":"json","retmax":20})
    ids=r.json()["esearchresult"]["idlist"]
    print("clinvar ids:", ids)
    if ids:
        r2=get("https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi",
               params={"db":"clinvar","id":",".join(ids),"retmode":"json"})
        js=r2.json()["result"]
        for i in ids:
            d=js[i]
            vsl=d.get("variation_set",[])
            for v in vsl:
                loc=v.get("variation_loc",[])
                for l in loc:
                    print("  ", d.get("accession"), l.get("chr"), l.get("start"), l.get("ref"), l.get("alt"),
                          "| GRCh38:", (l.get("assembly") or ""), "|", v.get("cdna_change"), v.get("protein_change"))
except Exception as e:
    traceback.print_exc()

print()
print("### 3) GCS bucket listing for AlphaMissense release files")
for u in ["https://storage.googleapis.com/gcp-public-data--alphamissense/",
          "https://storage.googleapis.com/gcp-public-data--alphamissense/index.html",
          "https://storage.googleapis.com/gcp-public-data--alphamissense/AlphaMissense_aa_substitutions.tsv.gz"]:
    try:
        r=requests.get(u, timeout=60, headers={"User-Agent":"Mozilla/5.0"})
        print(u, "->", r.status_code, len(r.content))
        if r.status_code==200 and u.endswith("/"):
            names=re.findall(r"<Key>([^<]+)</Key>", r.text)
            for n in names[:60]: print("   ", n)
        elif r.status_code==200 and u.endswith("index.html"):
            print(r.text[:1500])
    except Exception as e:
        print(u,"ERR",type(e).__name__,e)
